     9→import org.springframework.web.bind.annotation.*;
    10→
    11→import java.util.Map;
    12→
    13→@RestController
    14→@Log4j2
    15→@RequestMapping("/webhook")
    16→@RequiredArgsConstructor
    17→public class WebhookController {
    18→
    19→    private final WebhookService webhookService;
    20→
    21→    @Value("${webhook.security.key}")
    22→    private String securityKey;
    23→
    24→    @PostMapping("/leadsquared/leaddetails")
    25→    public ResponseEntity<String> receiveWebhook(
    26→            @RequestHeader(value = "X-Webhook-Token", required = false) String token,
    27→            @RequestBody Map<String, Object> payload) {
    28→        log.info("Incoming webhook request");
    29→
    30→        if (token == null || !token.equals(securityKey)) {
    31→            log.warn("Unauthorized webhook request attempt");
    32→            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("Unauthorized");
    33→        }
    34→
    35→        webhookService.handleWebhook(payload);
    36→        return ResponseEntity.ok("Webhook received successfully");
    37→    }
    38→}
