     9→@RestController
    10→@RequestMapping(path = "/schedule")
    11→public class SchedulingController {
    12→
    13→    @Autowired
    14→    ExternalScheduler externalScheduler;
    15→
    16→    @Autowired
    17→    ScheduleConfigService scheduleConfigService;
    18→
    19→    @PostMapping("/addjob")
    20→    @ResponseBody
    21→    public String addJob(@RequestParam String name) {
    22→        String cronExpression = scheduleConfigService.findConfigExpression(name);
    23→        boolean result = externalScheduler.addJob(name,cronExpression);
    24→        if (result) {
    25→            return "Job successfully scheduled!";
    26→        }
    27→        return "There is already a job running for the specified name!";
    28→    }
    29→
    30→    @PostMapping("/removejob")
