   399→    private String extractDestinationNumber(String activityNote) {
   400→        // If the input is null or doesn't have the key, skip
   401→        if (activityNote == null || !activityNote.contains("DestinationNumber")) return null;
   402→
   403→        // Find the start index of the value
   404→        int start = activityNote.indexOf("DestinationNumber\":\"");
   405→        if (start == -1) return null;
   406→
   407→        // Move the index just past the key string to the start of the value
   408→        start += "DestinationNumber\":\"".length();
   409→
   410→        // Find the closing quote of the value
   411→        int end = activityNote.indexOf("\"", start);
   412→        if (end == -1) return null;
   413→
   414→        // Return the substring containing just the destination number
   415→        return activityNote.substring(start, end);
   416→    }
